{"packet_id":"D084-01","doc_id":"D084","jurisdiction":"Santa Ana, CA","category":"rent_increase_limits","lifecycle":"enacted","title":"Santa Ana Rent Stabilization Ordinance maximum allowable rent increase","requirement":"A landlord may not raise rent by more than 3% of current rent or 80% of the CPI change, whichever is less; the cap is 2.87% for September 1, 2026 through August 31, 2027. Registration pass-through fees are capped at $50 per unit per month.","key_value":"2.87% for 2026-09-01 to 2027-08-31; 3% of current rent or 80% of CPI change, whichever is less","coverage_conditions":"The page does not state building-age, unit-count or owner-occupancy limits; it addresses Santa Ana renters and landlords generally.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":null},"exemptions":null,"penalty":"A landlord charging a pass-through fee above $50 must reimburse the tenant for the overpayment; tenants may petition to contest unauthorized increases or pass-through costs.","effective_date":"2026-09-01","citation":"Santa Ana Rent Stabilization and Just Cause Eviction Ordinance","quoted_span":"The increase cannot be more than 3% of your current rent or 80% of the Consumer Price Index (CPI) change, whichever is less.","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D084-01","doc_id":"D084","jurisdiction":"Santa Ana, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Santa Ana just cause eviction requirement and relocation assistance","requirement":"A landlord must have a valid reason to evict a tenant, such as nonpayment of rent, breach of the lease, or the landlord moving into the property; for certain evictions the landlord may have to help pay moving costs.","key_value":null,"coverage_conditions":"The page does not state building-age, unit-count or owner-occupancy limits; it addresses Santa Ana renters and landlords generally.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":null},"exemptions":null,"penalty":null,"effective_date":null,"citation":"Santa Ana Rent Stabilization and Just Cause Eviction Ordinance","quoted_span":"Your landlord must have a valid reason to evict you. This could be for not paying rent, breaking the lease, or if the landlord wants to move into the property themselves.","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
